 {id:'battery',name:'Energiacella',icon:'🔋',price:18000},{id:'screen',name:'OLED kijelző',icon:'▣',price:22000},{id:'ssd',name:'NVMe tárhely',icon:'▤',price:14000},{id:'ram',name:'Memóriamodul',icon:'▥',price:18000},{id:'cpu',name:'Processzor',icon:'▦',price:35000},{id:'gpu',name:'Grafikus kártya',icon:'▰',price:65000},{id:'case',name:'Gépház és táp',icon:'▧',price:25000},
 {id:'consolePower',name:'Konzol tápegység',icon:'⚡',price:26000},{id:'consoleFan',name:'Konzol ventilátor',icon:'❄',price:21000},{id:'hdmi',name:'HDMI modul',icon:'▱',price:19000},{id:'vrDisplay',name:'VR kijelzőmodul',icon:'◉',price:42000},{id:'motion',name:'Mozgásérzékelő',icon:'⌁',price:31000},{id:'lens',name:'Optikai lencsepár',icon:'◌',price:28000},{id:'wheelMotor',name:'Force feedback motor',icon:'⚙',price:38000},{id:'pedal',name:'Pedálszenzor',icon:'⌄',price:24000},{id:'usb',name:'USB vezérlőpanel',icon:'⌘',price:18000},
 {id:'phoneBoard',name:'Telefon alaplap',icon:'▨',price:68000,level:30},{id:'camera',name:'Kameramodul',icon:'◉',price:34000,level:30},{id:'controllerBoard',name:'Kontroller vezérlőlap',icon:'⌘',price:42000,level:30},{id:'sticks',name:'Analóg karpár',icon:'◈',price:23000,level:30}
