const qualities={used:{name:'Használt',price:.65,sell:.85,xp:0},normal:{name:'Normál',price:1,sell:1,xp:0},premium:{name:'Prémium',price:1.55,sell:1.25,xp:.1}};
const blueprints=[
 {id:'phonefix',name:'Hibás Nova telefon',icon:'📱',buy:8000,sell:65000,parts:['screen','battery'],fault:'Betört kijelző és gyenge akkumulátor.',level:1},
 {id:'laptopfix',name:'Hibás Pulse laptop',icon:'💻',buy:18000,sell:92000,parts:['ssd','battery','ram'],fault:'Lassú tárhely és instabil memória.',level:3},
 {id:'pcbuild',name:'Egyedi gamer PC',icon:'🖥️',buy:15000,sell:230000,parts:['case','cpu','ram','ssd','gpu'],fault:'Építs teljes gépet válogatott alkatrészekből.',level:5},
 {id:'consolefix',name:'Hibás játékkonzol',icon:'🎮',buy:42000,sell:175000,parts:['consolePower','consoleFan','hdmi','ssd'],fault:'Tápellátási és hűtési hibák.',level:10,gear:'consoleStation'},
 {id:'vrfix',name:'Hibás VR-szemüveg',icon:'🥽',buy:52000,sell:225000,parts:['vrDisplay','motion','lens','battery'],fault:'Pontatlan követés és kijelzőhiba.',level:10,gear:'vrToolkit'},
 {id:'racingfix',name:'Hibás játékkormány',icon:'🏎️',buy:46000,sell:195000,parts:['wheelMotor','pedal','usb'],fault:'Gyenge visszacsatolás és hibás pedál.',level:10,gear:'racingRig'},
 {id:'printphone',name:'3D-nyomtatott Nova telefon',icon:'📲',buy:0,sell:390000,parts:['phoneBoard','screen','battery','camera'],fault:'Nyomtass üres készülékházat, majd építsd be az elektronikát.',level:30,printer:true},
 {id:'printcontroller',name:'3D-nyomtatott Pro kontroller',icon:'🕹️',buy:0,sell:285000,parts:['controllerBoard','sticks','battery','usb'],fault:'Nyomtass egyedi burkolatot, majd szereld be a vezérlést.',level:30,printer:true}
];
const codes=['VIZSGALAT','ARAMKOR','KIJELZO','TARHELY','HUTES','AKKUMULATOR'];
const emptyWorkshop={parts:{},projects:[],finished:[],marketListings:[],nextId:1,wheelReadyAt:0,wheelSpins:0,customerOffer:null,offerExpiresAt:0,activeOrder:null,employees:[],employeeTimers:{},employeePending:0,lastEmployeeHistory:0,printerOwned:false,storeOwned:false,storeUpgrades:[],storeStaff:[],storeNextPayAt:0,storePending:0,lastStoreHistory:0};
let workshop=loadWorkshop(),game={mode:null,projectId:null,index:0,sequence:[]},wheelBusy=false;
function migrateParts(parts={}){const result={};Object.entries(parts).forEach(([id,value])=>{result[id]=typeof value==='number'?{used:0,normal:value,premium:0}:{used:0,normal:0,premium:0,...value}});return result}
function loadWorkshop(){try{const saved=JSON.parse(localStorage.getItem('voltmarket-workshop')||'{}');return {...emptyWorkshop,...saved,parts:migrateParts(saved.parts),projects:saved.projects||[],finished:saved.finished||[],marketListings:saved.marketListings||[],employees:saved.employees||[],employeeTimers:saved.employeeTimers||{},storeUpgrades:saved.storeUpgrades||[],storeStaff:saved.storeStaff||[]}}catch{return {...emptyWorkshop,parts:{},projects:[],finished:[],marketListings:[],employees:[],employeeTimers:{},storeUpgrades:[],storeStaff:[]}}}
function saveWorkshop(){localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop));renderWorkshop();renderEmployees();renderStore();updateWheel()}
function stock(id,q='normal'){return workshop.parts[id]?.[q]||0}
function ensurePart(id){workshop.parts[id]??={used:0,normal:0,premium:0};return workshop.parts[id]}
function partName(id){return workshopParts.find(p=>p.id===id)?.name||id}
function projectByUid(uid){return workshop.projects.find(p=>p.uid===Number(uid))}
function blueprint(id){return blueprints.find(b=>b.id===id)}
function blueprintAccess(b){return state.level>=b.level&&(!b.gear||state.owned.includes(b.gear))&&(!b.printer||workshop.printerOwned)}
function accessText(b){const missing=[];if(state.level<b.level)missing.push(`${b.level}. szint`);if(b.gear&&!state.owned.includes(b.gear))missing.push(getProductMeta(b.gear).name);if(b.printer&&!workshop.printerOwned)missing.push('3D nyomtató');return missing.join(' + ')}
function renderWorkshop(){
 const partTotal=Object.values(workshop.parts).reduce((sum,group)=>sum+Object.values(group).reduce((a,b)=>a+b,0),0);
 document.querySelector('#partCount').textContent=`${partTotal} db`;document.querySelector('#projectCount').textContent=`${workshop.projects.length} projekt`;document.querySelector('#finishedCount').textContent=`${workshop.finished.length} eszköz`;
 document.querySelector('#salvageGrid').innerHTML=blueprints.filter(b=>!b.printer).map(b=>{const open=blueprintAccess(b);return `<article class="salvage-card ${open?'':'locked-card'}"><div class="salvage-top"><span class="device-icon">${b.icon}</span><div><h3>${b.name}</h3><span class="category">${open?`VÁRHATÓ ELADÁS: ${fmt(b.sell)} CR`:`🔒 ${accessText(b)}`}</span></div></div><p>${b.fault}</p><div class="trade-row"><strong>${fmt(b.buy)} CR</strong><button class="small-btn salvage-buy" data-blueprint="${b.id}" ${open?'':'disabled'}>${open?'Projekt megvétele':'Zárolva'}</button></div></article>`}).join('');
 document.querySelector('#partsGrid').innerHTML=workshopParts.map(p=>{const open=state.level>=(p.level||1);return `<article class="part-card ${open?'':'locked-card'}"><div class="part-top"><span class="part-icon">${p.icon}</span><div><h3>${p.name}</h3><span class="category">${open?`H ${stock(p.id,'used')} · N ${stock(p.id)} · P ${stock(p.id,'premium')}`:`🔒 ${p.level}. SZINT`}</span></div></div><div class="quality-shop">${Object.entries(qualities).map(([q,v])=>`<button class="quality-buy ${q}" data-part="${p.id}" data-quality="${q}" ${open?'':'disabled'}><span>${v.name}</span><strong>${fmt(p.price*v.price)} CR</strong></button>`).join('')}</div></article>`}).join('');
 document.querySelector('#projectGrid').innerHTML=workshop.projects.length?workshop.projects.map(renderProject).join(''):'<div class="empty-card">Nincs aktív projekt. Vegyél egy hibás eszközt a készletből.</div>';
 document.querySelector('#finishedGrid').innerHTML=workshop.finished.length?workshop.finished.map((f,i)=>{const b=blueprint(f.type),q=qualities[f.quality||'normal'],customer=f.source==='customer';return `<article class="finished-card"><span class="device-icon">${b.icon}</span><span class="project-stage">${q.name.toUpperCase()} // ${customer?'RENDELÉS':'KÉSZ'}</span><h3>${b.name}</h3><span class="profit">${customer?`${fmt(f.reward)} CR ügyféljutalom`:'Változó piaci ár'}</span><button class="primary ${customer?'deliver-order':'list-market'}" data-finished="${i}">${customer?'Átadás az ügyfélnek':'Piacra teszem'}</button></article>`}).join(''):'<div class="empty-card">A megjavított eszközök itt várják majd az eladást.</div>';
 renderCustomerMarket();renderPrinterLab();
}
const PRINTER_PRICE=850000;
function renderPrinterLab(){const el=document.querySelector('#printerLab');if(!el)return;const levelReady=state.level>=30;if(!workshop.printerOwned){el.innerHTML=`<div class="printer-lock ${levelReady?'ready':''}"><div class="printer-art">🖨️<span>3D</span></div><div><span class="eyebrow">LEVEL 30 // FAB LAB</span><h2>NovaForm 3D nyomtató</h2><p>Üres telefon- és kontrollerházakat nyomtathatsz. A belső elektronikát ezután külön kell megvásárolni, diagnosztizálni és összeszerelni.</p></div><button class="primary buy-printer" ${levelReady?'':'disabled'}>${levelReady?`${fmt(PRINTER_PRICE)} CR – Megvásárolom`:'30. szinten nyílik meg'}</button></div>`;return}el.innerHTML=`<div class="printer-console"><div class="printer-head"><div><span class="eyebrow">NOVAFORM // ONLINE</span><h2>3D gyártólabor</h2><p>Válassz tervet, majd teljesítsd az egérvezérelt nyomtatási pályát.</p></div><span class="printer-online">● ÜZEMKÉSZ</span></div><div class="print-blueprints">${blueprints.filter(b=>b.printer).map(b=>`<article><span class="device-icon">${b.icon}</span><div><h3>${b.name}</h3><p>${b.fault}</p><strong>Várható piaci alapár: ${fmt(b.sell)} CR</strong></div><button class="primary start-print" data-print="${b.id}">Nyomtatás indítása</button></article>`).join('')}</div></div>`}
function buyPrinter(){if(workshop.printerOwned)return;if(state.level<30)return toast('A 3D nyomtató a 30. szinten válik elérhetővé.');if(state.balance<PRINTER_PRICE)return toast('Nincs elég kredited a 3D nyomtatóhoz.');state.balance-=PRINTER_PRICE;workshop.printerOwned=true;addHistory('NovaForm 3D nyomtató',-PRINTER_PRICE);save();saveWorkshop();toast('A 3D gyártólabor üzemkész.')}
function startPrint(type){const b=blueprint(type),cost=type==='printphone'?26000:18000;if(!b?.printer||!workshop.printerOwned)return;if(state.balance<cost)return toast(`A nyomtatási anyaghoz ${fmt(cost)} CR szükséges.`);startCircuitGame('printing',null,type,8,cost)}
function renderProject(p){const b=blueprint(p.type),q=p.quality||'normal',ready=b.parts.every(id=>stock(id,q)>0),open=blueprintAccess(b),customer=p.source==='customer';return `<article class="project-card ${open?'':'locked-card'}"><span class="project-stage">${customer?'ÜGYFÉL // ':''}${p.diagnosed?'ALKATRÉSZEKRE VÁR':'DIAGNOSZTIKA'}</span><h3>${b.icon} ${b.name}</h3><p>${open?(p.diagnosed?(customer?`${qualities[q].name} minőséget kért az ügyfél.`:'Válassz minőséget, majd szereld össze.'):'Egyetlen diagnosztikai feladat szükséges.'):`🔒 ${accessText(b)}`}</p><div class="quality-tabs">${Object.entries(qualities).map(([id,v])=>`<button class="quality-select ${q===id?'active':''}" data-project="${p.uid}" data-project-quality="${id}" ${p.diagnosed&&open&&!customer?'':'disabled'}>${v.name}</button>`).join('')}</div><div class="needs">${b.parts.map(id=>`<b class="${stock(id,q)>0?'have':''}">${partName(id)} ${stock(id,q)>0?'✓':'×'}</b>`).join('')}</div><button class="primary ${p.diagnosed?'assemble':'diagnose'}" data-project="${p.uid}" ${!open||(p.diagnosed&&!ready)?'disabled':''}>${!open?'Zárolva':p.diagnosed?(ready?'Összeszerelés indítása':'Hiányzó alkatrész'):'Diagnosztika indítása'}</button></article>`}
function buySalvage(type){const b=blueprint(type);if(!blueprintAccess(b))return toast(`Még hiányzik: ${accessText(b)}`);if(state.balance<b.buy)return toast('Nincs elég kredited ehhez a projekthez.');state.balance-=b.buy;workshop.projects.push({uid:workshop.nextId++,type,diagnosed:false,quality:'normal',source:'self',investment:b.buy});addHistory(`Hibás eszköz: ${b.name}`,-b.buy);save();saveWorkshop();toast('A hibás eszköz a munkapadra került.')}
function buyPart(id,q){const p=workshopParts.find(x=>x.id===id),quality=qualities[q];if(!p||state.level<(p.level||1))return toast(`${p?.level||1}. szint szükséges ehhez az alkatrészhez.`);const price=Math.round(p.price*quality.price);if(state.balance<price)return toast('Nincs elég kredited az alkatrészhez.');state.balance-=price;ensurePart(id)[q]++;addHistory(`${quality.name} ${p.name}`,-price);save();saveWorkshop();toast(`${quality.name} ${p.name} megvásárolva.`)}
function setProjectQuality(uid,q){const p=projectByUid(uid);if(p&&qualities[q]){p.quality=q;saveWorkshop()}}
function openGame(){document.querySelector('#gameModal').classList.add('open');document.querySelector('#gameModal').setAttribute('aria-hidden','false')}
function closeGame(){document.querySelector('#gameModal').classList.remove('open');document.querySelector('#gameModal').setAttribute('aria-hidden','true');document.querySelector('#typingInput').style.display='block';document.querySelector('#typingInput').disabled=false;document.querySelector('#typingInput').value='';document.querySelector('#circuitGame').innerHTML='';document.querySelector('#circuitGame').classList.remove('active');document.querySelector('.game-box p').textContent='Teljesítsd az egyszeri diagnosztikai feladatot.';document.querySelectorAll('.assembly-options').forEach(x=>x.remove());game.mode=null}
function startDiagnostic(uid){const p=projectByUid(uid);if(!p||p.diagnosed)return;if(blueprint(p.type).printer)return startCircuitGame('circuit',Number(uid),null,7,0);game={mode:'typing',projectId:Number(uid),index:0,sequence:[]};openGame();document.querySelector('.game-box p').textContent='Írd be egyszer pontosan a megjelenő szót.';document.querySelector('#typingInput').style.display='block';document.querySelector('#typingInput').disabled=false;document.querySelector('#targetText').textContent=codes[Math.floor(Math.random()*codes.length)];document.querySelector('#gameProgress').textContent='0 / 1';document.querySelector('#gameTimer').textContent='EGYSZERI ELLENŐRZÉS';document.querySelector('#typingInput').focus()}
function startCircuitGame(mode,projectId,printType,total,cost=0){game={mode,projectId,printType,index:0,total,cost};openGame();const circuit=document.querySelector('#circuitGame');document.querySelector('#typingInput').style.display='none';document.querySelector('#targetText').textContent=mode==='printing'?'Kövesd a nyomtatófej útvonalát!':'Kapcsold össze sorrendben az áramköri pontokat!';document.querySelector('.game-box p').textContent='Kattints az izzó pontra, majd kövesd a következő csomópontot. Hibás kattintásnál a sorozat újraindul.';document.querySelector('#gameTimer').textContent=mode==='printing'?'3D NYOMTATÁS':'ÁRAMKÖRI TESZT';document.querySelector('#gameProgress').textContent=`0 / ${total}`;circuit.classList.add('active');circuit.innerHTML=Array.from({length:total},(_,i)=>{const angle=i/total*Math.PI*2-.9,radius=i%2?34:25,left=50+Math.cos(angle)*radius,top=50+Math.sin(angle)*radius;return `<button class="circuit-node ${i===0?'current':''}" data-node="${i}" style="left:${left}%;top:${top}%" aria-label="${i+1}. áramköri pont"><span>${i+1}</span></button>`}).join('')}
function circuitClick(node){if(!['printing','circuit'].includes(game.mode))return;const n=Number(node.dataset.node),nodes=[...document.querySelectorAll('.circuit-node')];if(n!==game.index){game.index=0;nodes.forEach((el,i)=>el.className=`circuit-node ${i===0?'current':''}`);document.querySelector('#gameProgress').textContent=`0 / ${game.total}`;return}node.classList.remove('current');node.classList.add('done');game.index++;document.querySelector('#gameProgress').textContent=`${game.index} / ${game.total}`;if(game.index<game.total){nodes[game.index].classList.add('current');return}if(game.mode==='printing'){state.balance-=game.cost;const b=blueprint(game.printType);workshop.projects.push({uid:workshop.nextId++,type:b.id,diagnosed:false,quality:'normal',source:'self',investment:game.cost});addHistory(`3D nyomtatási anyag: ${b.name}`,-game.cost);state.xp+=55;toast('A burkolat elkészült. Következhet az áramköri diagnosztika.')}else{const p=projectByUid(game.projectId);if(p)p.diagnosed=true;state.xp+=65;toast('Áramköri diagnosztika sikeres: +65 XP')}updateLevel();save();saveWorkshop();closeGame()}
function typingInput(e){if(game.mode!=='typing')return;if(e.target.value.trim().toUpperCase()===document.querySelector('#targetText').textContent){const projectId=game.projectId;game.mode='checking';e.target.disabled=true;document.querySelector('.game-box p').textContent='A rendszer ellenőrzi az eredményt…';document.querySelector('#targetText').innerHTML='<span class="diagnostic-loading"><i class="diagnostic-spinner"></i><b>Diagnosztika folyamatban</b><small>Az eredmény feldolgozása</small></span>';document.querySelector('#gameProgress').textContent='ELLENŐRZÉS';document.querySelector('#gameTimer').textContent='FOLYAMATBAN';setTimeout(()=>{if(game.mode!=='checking'||game.projectId!==projectId)return;const p=projectByUid(projectId);if(p){p.diagnosed=true;state.xp+=25;updateLevel();save();saveWorkshop()}closeGame();toast('Diagnosztika sikeres: +25 XP')},2800)}}
function startAssembly(uid){const p=projectByUid(uid),b=blueprint(p.type),q=p.quality||'normal';if(!b.parts.every(id=>stock(id,q)>0))return;game={mode:'assembly',projectId:Number(uid),index:0,sequence:[...b.parts]};openGame();document.querySelector('.game-box p').textContent='Szereld be az alkatrészeket a kijelzett sorrendben.';document.querySelector('#typingInput').style.display='none';document.querySelector('#targetText').textContent=`Következő: ${partName(game.sequence[0])}`;document.querySelector('#gameTimer').textContent='PONTOS SORREND';document.querySelector('#gameProgress').textContent=`0 / ${game.sequence.length}`;const opts=document.createElement('div');opts.className='assembly-options filters';opts.innerHTML=[...b.parts].sort(()=>Math.random()-.5).map(id=>`<button class="filter assembly-part" data-assembly-part="${id}">${partName(id)}</button>`).join('');document.querySelector('#targetText').after(opts)}
function chooseAssembly(id){if(game.mode!=='assembly')return;if(id!==game.sequence[game.index]){game.index=0;document.querySelector('#gameProgress').textContent=`0 / ${game.sequence.length}`;document.querySelector('#targetText').textContent=`Hibás sorrend! Kezdd újra: ${partName(game.sequence[0])}`;return}game.index++;document.querySelector('#gameProgress').textContent=`${game.index} / ${game.sequence.length}`;if(game.index===game.sequence.length)return finishAssembly();document.querySelector('#targetText').textContent=`Következő: ${partName(game.sequence[game.index])}`}
function finishAssembly(){const p=projectByUid(game.projectId),b=blueprint(p.type),q=p.quality||'normal',partsCost=b.parts.reduce((sum,id)=>sum+Math.round(workshopParts.find(x=>x.id===id).price*qualities[q].price),0);b.parts.forEach(id=>ensurePart(id)[q]--);workshop.projects=workshop.projects.filter(x=>x.uid!==p.uid);workshop.finished.push({type:p.type,quality:q,source:p.source||'self',orderId:p.orderId||null,reward:p.reward||0,investment:(p.investment||0)+partsCost,completed:Date.now()});state.xp+=Math.round(45*(1+qualities[q].xp));updateLevel();save();saveWorkshop();closeGame();toast(p.source==='customer'?'A rendelés elkészült, add át az ügyfélnek.':'Sikeres összeszerelés: tedd piacra az eszközt.')}

const customerNames=['Dóra','Márk','Nóra','Bence','Lili','Áron','Emma','Zalán'];
function nextOfferDelay(){return 20000+Math.floor(Math.random()*5001)}
function generateCustomerOffer(){if(workshop.activeOrder)return;const pool=blueprints.filter(b=>!b.printer&&blueprintAccess(b)),b=pool[Math.floor(Math.random()*pool.length)]||blueprints[0],qualityKeys=state.level>=8?['used','normal','premium']:['used','normal'],quality=qualityKeys[Math.floor(Math.random()*qualityKeys.length)],reward=Math.round(b.sell*qualities[quality].sell*1.16);workshop.customerOffer={id:`order-${Date.now()}`,customer:customerNames[Math.floor(Math.random()*customerNames.length)],type:b.id,quality,reward,xp:35+Math.round(b.level*2)};workshop.offerExpiresAt=Date.now()+nextOfferDelay()}
function acceptOffer(){if(workshop.activeOrder||!workshop.customerOffer)return;const order=workshop.customerOffer;workshop.activeOrder={...order};workshop.projects.push({uid:workshop.nextId++,type:order.type,diagnosed:false,quality:order.quality,source:'customer',orderId:order.id,reward:order.reward,investment:0});workshop.customerOffer=null;workshop.offerExpiresAt=0;saveWorkshop();toast(`${order.customer} megrendelése a munkapadra került.`)}
function declineOffer(){if(workshop.activeOrder)return;workshop.customerOffer=null;workshop.offerExpiresAt=Date.now()+nextOfferDelay();saveWorkshop();toast('Az ajánlat elutasítva. A következő ügyfél 20–25 másodperc múlva érkezik.')}
function deliverOrder(index){const item=workshop.finished[index],order=workshop.activeOrder;if(!item||item.source!=='customer'||!order||item.orderId!==order.id)return toast('Ez nem az aktív ügyfél rendelése.');state.balance+=order.reward;state.xp+=order.xp;updateLevel();addHistory(`Ügyfélrendelés: ${blueprint(item.type).name}`,order.reward);workshop.finished.splice(index,1);workshop.activeOrder=null;generateCustomerOffer();save();saveWorkshop();toast(`Megrendelés átadva: +${fmt(order.reward)} CR`)}
function specialistMarketBonus(type){if(workshop.employees.includes('system')&&['laptopfix','pcbuild'].includes(type))return .03;if(workshop.employees.includes('senior')&&['consolefix','vrfix','racingfix'].includes(type))return .05;return 0}
function listOnMarket(index){const item=workshop.finished[index];if(!item||item.source==='customer')return;const b=blueprint(item.type),q=qualities[item.quality||'normal'],specialist=1+specialistMarketBonus(item.type),reference=Math.round(b.sell*q.sell*specialist),minimum=Math.ceil((item.investment||0)*1.08),salePrice=Math.max(minimum,Math.round(reference*(.94+Math.random()*.19))),sellAt=Date.now()+10000+Math.floor(Math.random()*10001);workshop.marketListings.push({...item,listingId:`market-${Date.now()}-${index}`,salePrice,sellAt});workshop.finished.splice(index,1);saveWorkshop();toast('A termék felkerült a piacra. A vevő érkezési ideje rejtett.')}
function settleMarket(){const sold=workshop.marketListings.filter(x=>Date.now()>=x.sellAt);if(!sold.length)return false;sold.forEach(item=>{state.balance+=item.salePrice;state.xp+=20;addHistory(`Piaci eladás: ${blueprint(item.type).name}`,item.salePrice)});workshop.marketListings=workshop.marketListings.filter(x=>Date.now()<x.sellAt);updateLevel();save();saveWorkshop();toast(`${sold.length} piaci termék elkelt.`);return true}
function renderCustomerMarket(){const offerEl=document.querySelector('#customerOffer'),marketEl=document.querySelector('#marketGrid');if(!offerEl||!marketEl)return;if(workshop.activeOrder){const o=workshop.activeOrder,b=blueprint(o.type);offerEl.innerHTML=`<article class="offer-card active-order"><span class="status-dot"></span><span class="category">ELFOGADOTT RENDELÉS</span><h3>${o.customer}: ${b.icon} ${b.name}</h3><p>Elvárt minőség: <strong>${qualities[o.quality].name}</strong></p><div class="offer-reward">${fmt(o.reward)} CR · +${o.xp} XP</div><small>Nincs határidő. A projekt a munkapadon található.</small></article>`}else if(!workshop.customerOffer){const left=Math.max(0,Math.ceil((workshop.offerExpiresAt-Date.now())/1000));offerEl.innerHTML=`<article class="offer-card waiting-offer"><span class="customer-loader"></span><span class="category">ÜGYFÉLFOGADÁS</span><h3>Következő ügyfél keresése…</h3><p>Új ajánlat várható ${left} másodperc múlva.</p></article>`}else{const o=workshop.customerOffer,b=blueprint(o.type),left=Math.max(0,Math.ceil((workshop.offerExpiresAt-Date.now())/1000));offerEl.innerHTML=`<article class="offer-card"><span class="category">${o.customer.toUpperCase()} AJÁNLATA</span><h3>${b.icon} ${b.name}</h3><p>Kért minőség: <strong>${qualities[o.quality].name}</strong></p><div class="offer-reward">${fmt(o.reward)} CR · +${o.xp} XP</div><small>Az ajánlat cseréje: ${left} mp</small><div class="offer-actions"><button class="small-btn accept-offer">Elfogadás</button><button class="small-btn decline-offer">Elutasítás</button></div></article>`}marketEl.innerHTML=workshop.marketListings.length?workshop.marketListings.map(item=>{const b=blueprint(item.type);return `<article class="market-card"><span class="device-icon">${b.icon}</span><div><strong>${b.name}</strong><small>${qualities[item.quality||'normal'].name} minőség</small><span class="market-searching">● Vevő keresése…</span></div></article>`}).join(''):'<div class="mini-empty">Nincs piacon lévő termék.</div>'}

const employees=[
 {id:'junior',level:15,title:'Junior szerviztechnikus',profession:'Telefonok és egyszerű javítások',benefit:'Kis eséllyel használt telefonalkatrészt talál.',price:150000,base:200,icon:'🧑‍🔧'},
 {id:'system',level:20,title:'Rendszertechnikus',profession:'Laptopok és PC-rendszerek',benefit:'+3% piaci ár laptop és PC eladásakor.',price:300000,base:400,icon:'🧑‍💻'},
 {id:'senior',level:25,title:'Senior műhelyvezető',profession:'Konzol, VR és szimulátor technológia',benefit:'+5% piaci ár konzol, VR és kormány eladásakor.',price:500000,base:600,icon:'👨‍🏭'}
];
function employeeCycle(){return Math.max(6,Math.round(10*(1-Math.min(.4,cooldownCut()+speedBoost()))))}
function employeeIncome(e){return Math.round(e.base*(1+bonus()))}
function renderEmployees(){const grid=document.querySelector('#employeeGrid'),summary=document.querySelector('#employeeSummary');if(!grid||!summary)return;const hired=employees.filter(e=>workshop.employees.includes(e.id)),cycle=employeeCycle(),total=hired.reduce((sum,e)=>sum+employeeIncome(e),0);summary.innerHTML=`<div><span>AKTÍV MUNKATÁRS</span><strong>${hired.length} / ${employees.length}</strong></div><div><span>CSAPATBEVÉTEL</span><strong>${fmt(total)} CR / ${cycle} mp</strong></div><div><span>FELHALMOZOTT</span><strong>${fmt(workshop.employeePending)} CR</strong></div>`;grid.innerHTML=employees.map(e=>{const owned=workshop.employees.includes(e.id),locked=state.level<e.level;return `<article class="employee-card ${locked?'locked-card':''}"><span class="employee-icon">${e.icon}</span><span class="category">${e.level}. SZINT // ${e.profession}</span><h3>${e.title}</h3><p>Alap: ${fmt(e.base)} CR / 10 mp<br>Aktuális bónusszal: ${fmt(employeeIncome(e))} CR / ${cycle} mp</p><div class="employee-benefit">◆ ${e.benefit}</div><div class="employee-foot"><strong>${fmt(e.price)} CR</strong><button class="primary hire-employee" data-employee="${e.id}" ${owned||locked?'disabled':''}>${owned?'Alkalmazva':locked?'Zárolva':'Felvétel'}</button></div></article>`}).join('')}
function hireEmployee(id){const e=employees.find(x=>x.id===id);if(!e||workshop.employees.includes(id))return;if(state.level<e.level)return toast(`${e.level}. szint szükséges.`);if(state.balance<e.price)return toast('Nincs elég kredited az alkalmazott felvételéhez.');state.balance-=e.price;workshop.employees.push(id);workshop.employeeTimers[id]=Date.now()+employeeCycle()*1000;addHistory(`Alkalmazott: ${e.title}`,-e.price);save();saveWorkshop();toast(`${e.title} csatlakozott a csapathoz.`)}
function employeeTick(){const now=Date.now(),cycle=employeeCycle();let gained=0;employees.filter(e=>workshop.employees.includes(e.id)).forEach(e=>{const due=workshop.employeeTimers[e.id]||now+cycle*1000;if(now>=due){gained+=employeeIncome(e);workshop.employeeTimers[e.id]=now+cycle*1000;if(e.id==='junior'&&Math.random()<.02){const phonePart=Math.random()<.5?'battery':'screen';ensurePart(phonePart).used++;toast('A junior technikus talált egy használt telefonalkatrészt.')}}else workshop.employeeTimers[e.id]=due});if(!gained)return;state.balance+=gained;workshop.employeePending+=gained;if(!workshop.lastEmployeeHistory)workshop.lastEmployeeHistory=now;if(now-workshop.lastEmployeeHistory>=60000){addHistory('Összesített csapatbevétel',workshop.employeePending);workshop.employeePending=0;workshop.lastEmployeeHistory=now}save();saveWorkshop()}

/* Extra workshop specialist: repairs one purchased faulty device at a time. */
const repairEmployee={id:'repairLead',level:30,title:'Mester javítástechnikus',titleEn:'Master Repair Technician',profession:'Teljes körű hibás eszköz javítás',professionEn:'Full faulty-device repair',benefit:'Egy hibásan megvásárolt eszközt kezel egyszerre.',benefitEn:'Handles one purchased faulty device at a time.',price:3500000,icon:'🧑‍🔧'};
function repairEmployeeHired(){return workshop.repairEmployeeHired===true}
function repairText(hu,en){return state.language==='en'?en:hu}
function repairProjectOptions(){return workshop.projects.filter(p=>p.source==='self'&&!blueprint(p.type)?.printer&&!p.employeeJob).map(p=>{const b=blueprint(p.type);return `<option value="${p.uid}">${b.icon} ${b.name}</option>`}).join('')}
function renderRepairEmployee(){const grid=document.querySelector('#employeeGrid');if(!grid)return;const old=document.querySelector('#repairEmployeeCard');old?.remove();const locked=state.level<repairEmployee.level,job=workshop.employeeJob;let body='';if(!repairEmployeeHired())body=`<p>${repairText('Egyetlen hibásan megvásárolt terméket javít automatikusan. Nagyon drága, de tehermentesíti a műhelyt.','Repairs one purchased faulty device automatically. Very expensive, but it frees your workshop.')}</p><div class="employee-benefit">◆ ${repairText(repairEmployee.benefit,repairEmployee.benefitEn)}</div><div class="employee-foot"><strong>${fmt(repairEmployee.price)} CR</strong><button class="primary hire-repair-employee" ${locked?'disabled':''}>${locked?repairText('Zárolva','Locked'):repairText('Felvétel','Hire')}</button></div>`;else if(!job){const options=repairProjectOptions();body=`<p>${repairText('Válassz egy hibás, saját projektet. A diagnosztika 1 percig tart.','Choose one faulty project you purchased. Diagnosis takes 1 minute.')}</p>${options?`<div class="repair-controls"><select id="repairProjectSelect"><option value="">${repairText('Válassz terméket','Choose a product')}</option>${options}</select><select id="repairQualitySelect">${Object.entries(qualities).map(([id,q])=>`<option value="${id}">${q.name}</option>`).join('')}</select><button class="primary start-repair-employee">${repairText('Munka átadása','Assign repair')}</button></div>`:`<div class="mini-empty">${repairText('Nincs átadható hibás projekt.','No eligible faulty project.')}</div>`}`;}else if(job.status==='diagnosing'){body=`<p>${repairText('Diagnosztika folyamatban.','Diagnosis in progress.')}</p><div class="employee-progress"><span style="width:${Math.max(3,Math.min(100,(1-(job.readyAt-Date.now())/60000)*100))}%"></span></div><small>${Math.max(0,Math.ceil((job.readyAt-Date.now())/1000))} mp</small>`}else if(job.status==='assemblyPrompt'){const p=projectByUid(job.projectId),b=p&&blueprint(p.type);body=`<p>${repairText(`${b?.name||'A termék'} diagnosztikája kész. Indulhat az összeszerelés?`,'Diagnosis complete. Start assembly?')}</p><div class="employee-benefit">${repairText('Kiválasztott minőség:','Selected quality:')} <strong>${qualities[job.quality].name}</strong><br>${repairText('Alkatrészek költsége:','Parts cost:')} <strong>${fmt(job.partsCost)} CR</strong></div><button class="primary start-employee-assembly">${repairText('Összeszerelés indítása','Start assembly')}</button>`}else{body=`<p>${repairText('Összeszerelés folyamatban.','Assembly in progress.')}</p><div class="employee-progress"><span style="width:${Math.max(3,Math.min(100,(1-(job.readyAt-Date.now())/120000)*100))}%"></span></div><small>${Math.max(0,Math.ceil((job.readyAt-Date.now())/1000))} mp</small>`}grid.insertAdjacentHTML('beforeend',`<article id="repairEmployeeCard" class="employee-card repair-employee-card ${locked?'locked-card':''}"><span class="employee-icon">${repairEmployee.icon}</span><span class="category">${repairEmployee.level}. SZINT // ${repairText(repairEmployee.profession,repairEmployee.professionEn)}</span><h3>${repairText(repairEmployee.title,repairEmployee.titleEn)}</h3>${body}</article>`)}
const renderEmployeesBase=renderEmployees;renderEmployees=function(){renderEmployeesBase();renderRepairEmployee()};
function hireRepairEmployee(){if(repairEmployeeHired())return;if(state.level<repairEmployee.level)return toast(repairText('A 30. szint szükséges.','Level 30 is required.'));if(state.balance<repairEmployee.price)return toast(repairText('Nincs elég kredited ehhez az alkalmazotthoz.','You cannot afford this technician.'));state.balance-=repairEmployee.price;workshop.repairEmployeeHired=true;addHistory(repairText('Mester javítástechnikus','Master Repair Technician'),-repairEmployee.price);save();saveWorkshop();toast(repairText('A mester készen áll egy hibás termék javítására.','The master is ready for a faulty-device repair.'))}
function startRepairEmployee(){if(!repairEmployeeHired()||workshop.employeeJob)return;const projectId=Number(document.querySelector('#repairProjectSelect')?.value),quality=document.querySelector('#repairQualitySelect')?.value||'normal',p=projectByUid(projectId),b=p&&blueprint(p.type);if(!p||p.source!=='self'||b?.printer)return toast(repairText('Csak hibásan megvásárolható terméket választhatsz.','Only purchased faulty devices are eligible.'));const partsCost=b.parts.reduce((sum,id)=>sum+Math.round(workshopParts.find(x=>x.id===id).price*qualities[quality].price),0);p.employeeJob=true;workshop.employeeJob={projectId,quality,partsCost,status:'diagnosing',readyAt:Date.now()+60000};saveWorkshop();toast(repairText('A mester elkezdte a diagnosztikát.','The master started the diagnosis.'))}
function startEmployeeAssembly(){const job=workshop.employeeJob,p=job&&projectByUid(job.projectId),b=p&&blueprint(p.type);if(!job||job.status!=='assemblyPrompt'||!p||!b)return;if(!b.parts.every(id=>stock(id,job.quality)>0))return toast(repairText('Nincs meg minden alkatrész ebben a minőségben.','Some parts of this quality are missing.'));if(state.balance<job.partsCost)return toast(repairText('Nincs elég kredited az alkatrészekhez.','You cannot afford these parts.'));b.parts.forEach(id=>ensurePart(id)[job.quality]--);state.balance-=job.partsCost;addHistory(`${repairText('Alkatrészek','Parts')}: ${b.name}`,-job.partsCost);job.status='assembling';job.readyAt=Date.now()+120000;save();saveWorkshop();toast(repairText('Az összeszerelés 2 percre elindult.','Assembly started for 2 minutes.'))}
const employeeTickBase=employeeTick;employeeTick=function(){employeeTickBase();const job=workshop.employeeJob;if(!job)return;if(job.status==='diagnosing'&&Date.now()>=job.readyAt){const p=projectByUid(job.projectId);if(!p){workshop.employeeJob=null;saveWorkshop();return}p.diagnosed=true;job.status='assemblyPrompt';toast(repairText('A mester befejezte a diagnosztikát. Választhatsz összeszerelést.','Diagnosis complete. You can start assembly.'));saveWorkshop()}else if(job.status==='assembling'&&Date.now()>=job.readyAt){const p=projectByUid(job.projectId),b=p&&blueprint(p.type);if(p&&b){workshop.projects=workshop.projects.filter(x=>x.uid!==p.uid);workshop.finished.push({type:p.type,quality:job.quality,source:'self',investment:(p.investment||0)+job.partsCost,completed:Date.now()});state.xp+=45;updateLevel();toast(repairText('A mester elkészült a termékkel. Tedd piacra!','The master finished the device. List it on the market!'))}workshop.employeeJob=null;save();saveWorkshop()}}

const STORE_PRICE=5000000,STORE_CYCLE=60;
const storeUpgrades=[
 {id:'interior',name:'Modern belső tér',icon:'🛋️',price:450000,bonus:.12,desc:'+12% üzleti bevétel.'},
 {id:'shelves',name:'Világító bemutatópolcok',icon:'💡',price:700000,bonus:.18,desc:'+18% üzleti bevétel.'},
 {id:'counter',name:'Prémium szervizpult',icon:'🧰',price:950000,bonus:.2,desc:'+20% üzleti bevétel.'},
 {id:'sign',name:'Neon reklámtábla',icon:'📣',price:1250000,bonus:.25,desc:'+25% üzleti bevétel.'},
 {id:'expansion',name:'Plusz műhelyszárny',icon:'🏗️',price:1750000,bonus:.1,desc:'+10% bevétel és három új alkalmazotti hely.'},
 {id:'showroom',name:'Exkluzív bemutatóterem',icon:'✨',price:2400000,bonus:.35,desc:'+35% üzleti bevétel.'}
];
const storeStaff=[
 {id:'sales',name:'Tech értékesítő',icon:'🧑‍💼',price:800000,income:5000,desc:'Kezeli a vásárlókat és a bemutatópolcokat.'},
 {id:'printtech',name:'Additív gyártástechnikus',icon:'🧑‍🔬',price:1200000,income:8000,desc:'Felügyeli a 3D nyomtatást és a készletet.'},
 {id:'manager',name:'Üzletvezető',icon:'👩‍💼',price:1800000,income:12000,desc:'Összehangolja az üzlet és a műhely működését.'}
];
function storeMultiplier(){return 1+storeUpgrades.filter(u=>workshop.storeUpgrades.includes(u.id)).reduce((sum,u)=>sum+u.bonus,0)+bonus()}
function storeCycleIncome(){const staff=storeStaff.filter(e=>workshop.storeStaff.includes(e.id)).reduce((sum,e)=>sum+e.income,0);return Math.round((30000+staff)*storeMultiplier())}
function renderStore(){const status=document.querySelector('#storeStatus'),upgrades=document.querySelector('#storeUpgradeGrid'),staffGrid=document.querySelector('#storeStaffGrid'),staffSection=document.querySelector('#storeStaffSection');if(!status||!upgrades||!staffGrid)return;const ready=state.level>=35;if(!workshop.storeOwned){status.innerHTML=`<article class="store-purchase ${ready?'ready':''}"><div class="store-building">🏬<span>VOLT</span></div><div><span class="eyebrow">${ready?'BEFEKTETÉS ELÉRHETŐ':'35. SZINTEN NYÍLIK MEG'}</span><h2>VoltMarket zászlóshajó üzlet</h2><p>Magas belépési költség, de erős, percenkénti üzleti bevétel és hat fejlesztési lehetőség.</p><strong>${fmt(STORE_PRICE)} CR</strong></div><button class="primary buy-store" ${ready?'':'disabled'}>${ready?'Üzlet megvásárlása':'Zárolva'}</button></article>`;upgrades.innerHTML='';staffGrid.innerHTML='';staffSection.style.display='none';return}staffSection.style.display='block';const next=Math.max(0,Math.ceil((workshop.storeNextPayAt-Date.now())/1000));status.innerHTML=`<div class="store-dashboard"><div><span>ÜZLET ÁLLAPOTA</span><strong>NYITVA</strong></div><div><span>KÖVETKEZŐ BEVÉTEL</span><strong>${next} mp</strong></div><div><span>BEVÉTEL / 60 MP</span><strong>${fmt(storeCycleIncome())} CR</strong></div><div><span>FEJLESZTÉSEK</span><strong>${workshop.storeUpgrades.length} / ${storeUpgrades.length}</strong></div></div>`;upgrades.innerHTML=storeUpgrades.map((u,i)=>{const owned=workshop.storeUpgrades.includes(u.id),previous=i===0||workshop.storeUpgrades.includes(storeUpgrades[i-1].id);return `<article class="store-upgrade ${owned?'owned':''} ${previous?'':'locked-card'}"><span>${u.icon}</span><div><small>${i+1}. FEJLESZTÉSI SZINT</small><h3>${u.name}</h3><p>${u.desc}</p><strong>${fmt(u.price)} CR</strong></div><button class="small-btn buy-store-upgrade" data-upgrade="${u.id}" ${owned||!previous?'disabled':''}>${owned?'Kész':previous?'Fejlesztés':'Előző szükséges'}</button></article>`}).join('');const staffOpen=workshop.storeUpgrades.includes('expansion');staffGrid.innerHTML=storeStaff.map(e=>{const hired=workshop.storeStaff.includes(e.id);return `<article class="employee-card ${staffOpen?'':'locked-card'}"><span class="employee-icon">${e.icon}</span><span class="category">${staffOpen?'PLUSZ MŰHELY':'MŰHELYBŐVÍTÉS SZÜKSÉGES'}</span><h3>${e.name}</h3><p>${e.desc}</p><div class="employee-benefit">+${fmt(e.income)} CR minden üzleti ciklusban</div><div class="employee-foot"><strong>${fmt(e.price)} CR</strong><button class="primary hire-store-staff" data-store-staff="${e.id}" ${hired||!staffOpen?'disabled':''}>${hired?'Alkalmazva':staffOpen?'Felvétel':'Zárolva'}</button></div></article>`}).join('')}
const renderStoreBase=renderStore;renderStore=function(){renderStoreBase();if(!workshop.storeOwned){const upgrades=document.querySelector('#storeUpgradeGrid'),staffSection=document.querySelector('#storeStaffSection'),staffGrid=document.querySelector('#storeStaffGrid');if(!upgrades||!staffGrid)return;upgrades.innerHTML=`<div class="store-preview-note">${repairText('A bolt megvásárlása után ezek a fejlesztések és munkatársak válnak elérhetővé.','These upgrades and staff become available after purchasing the store.')}</div>`+storeUpgrades.map((u,i)=>`<article class="store-upgrade locked-card"><span>${u.icon}</span><div><small>${i+1}. ${repairText('FEJLESZTÉSI SZINT','UPGRADE TIER')}</small><h3>${repairText(u.name,u.name)}</h3><p>${repairText(u.desc,u.desc)}</p><strong>${fmt(u.price)} CR</strong></div><button class="small-btn" disabled>${repairText('Bolt szükséges','Store required')}</button></article>`).join('');staffSection.style.display='block';staffGrid.innerHTML=storeStaff.map(e=>`<article class="employee-card locked-card"><span class="employee-icon">${e.icon}</span><span class="category">${repairText('BOLTI MUNKATÁRS','STORE STAFF')}</span><h3>${e.name}</h3><p>${e.desc}</p><div class="employee-benefit">+${fmt(e.income)} CR / ${repairText('üzleti ciklus','business cycle')}</div><div class="employee-foot"><strong>${fmt(e.price)} CR</strong><button class="primary" disabled>${repairText('Bolt szükséges','Store required')}</button></div></article>`).join('')}}
const renderCustomerMarketBase=renderCustomerMarket;renderCustomerMarket=function(){renderCustomerMarketBase();const storeGrid=document.querySelector('#storeMarketGrid');if(!storeGrid)return;if(!workshop.storeOwned){storeGrid.innerHTML=`<div class="mini-empty">${repairText('A licitpiac az üzlet megvásárlása után nyílik meg.','The bidding market opens after purchasing the store.')}</div>`;return}const now=Date.now();storeGrid.innerHTML=workshop.marketListings.length?workshop.marketListings.map(item=>{const b=blueprint(item.type),left=Math.max(0,Math.ceil(((item.bidExpiresAt||now)-now)/1000));return `<article class="bid-card"><span class="device-icon">${b.icon}</span><div><strong>${b.name}</strong><small>${qualities[item.quality||'normal'].name} minőség</small><span class="bid-price">${fmt(item.bidPrice||item.salePrice)} CR</span><span class="bid-timer">Licit vége: ${left} mp</span></div><button class="primary accept-bid" data-listing="${item.listingId}">${repairText('Elfogadom','Accept')}</button></article>`}).join(''):`<div class="mini-empty">${repairText('Nincs aktív licit.','No active bids.')}</div>`}
const listOnMarketBase=listOnMarket;listOnMarket=function(index){if(!workshop.storeOwned)return listOnMarketBase(index);const item=workshop.finished[index];if(!item||item.source==='customer')return;const b=blueprint(item.type),q=qualities[item.quality||'normal'],reference=Math.round(b.sell*q.sell*(1+specialistMarketBonus(item.type))),minimum=Math.ceil((item.investment||0)*1.08),bidPrice=Math.max(minimum,Math.round(reference*(1.05+Math.random()*.35)));workshop.marketListings.push({...item,listingId:`bid-${Date.now()}-${index}`,bidPrice,bidExpiresAt:Date.now()+20000});workshop.finished.splice(index,1);saveWorkshop();toast(repairText('A termék bekerült a bolti licitpiacra.','The device entered the store bidding market.'))}
const settleMarketBase=settleMarket;settleMarket=function(){if(!workshop.storeOwned)return settleMarketBase();const now=Date.now();workshop.marketListings.forEach(item=>{if(!item.bidExpiresAt){item.bidExpiresAt=now+20000;item.bidPrice=item.salePrice||Math.ceil((item.investment||0)*1.12)}if(now>=item.bidExpiresAt){const b=blueprint(item.type),q=qualities[item.quality||'normal'],reference=Math.round(b.sell*q.sell*(1+specialistMarketBonus(item.type))),minimum=Math.ceil((item.investment||0)*1.08);item.bidPrice=Math.max(minimum,Math.round(reference*(1.05+Math.random()*.35)));item.bidExpiresAt=now+20000}});return false}
function acceptMarketBid(listingId){if(!workshop.storeOwned)return;const item=workshop.marketListings.find(x=>x.listingId===listingId);if(!item)return;const price=item.bidPrice||item.salePrice||0;state.balance+=price;state.xp+=25;addHistory(`Bolti licit: ${blueprint(item.type).name}`,price);workshop.marketListings=workshop.marketListings.filter(x=>x.listingId!==listingId);updateLevel();save();saveWorkshop();toast(repairText(`Licit elfogadva: +${fmt(price)} CR` ,`Bid accepted: +${fmt(price)} CR`))}

function buyStore(){if(workshop.storeOwned)return;if(state.level<35)return toast('Az üzlet a 35. szinten válik elérhetővé.');if(state.balance<STORE_PRICE)return toast('Még nincs elég kredited az üzlet megvásárlásához.');state.balance-=STORE_PRICE;workshop.storeOwned=true;workshop.storeNextPayAt=Date.now()+STORE_CYCLE*1000;addHistory('VoltMarket üzlet',-STORE_PRICE);save();saveWorkshop();toast('Megnyílt a saját VoltMarket üzleted!')}
function buyStore(){if(workshop.storeOwned)return;if(state.level<35)return toast('Az üzlet a 35. szinten válik elérhetővé.');if(state.balance<STORE_PRICE)return toast('Még nincs elég kredited az üzlet megvásárlásához.');state.balance-=STORE_PRICE;workshop.storeOwned=true;workshop.storeNextPayAt=Date.now()+STORE_CYCLE*1000;addHistory('VoltMarket üzlet',-STORE_PRICE);save();saveWorkshop();toast('Megnyílt a saját VoltMarket üzleted!')}
function buyStoreUpgrade(id){const index=storeUpgrades.findIndex(u=>u.id===id),u=storeUpgrades[index];if(!workshop.storeOwned||!u||workshop.storeUpgrades.includes(id))return;if(index>0&&!workshop.storeUpgrades.includes(storeUpgrades[index-1].id))return toast('Előbb az előző fejlesztést kell megvenned.');if(state.balance<u.price)return toast('Nincs elég kredited ehhez a fejlesztéshez.');state.balance-=u.price;workshop.storeUpgrades.push(id);addHistory(`Üzletfejlesztés: ${u.name}`,-u.price);save();saveWorkshop();toast(`${u.name} elkészült.`)}
function hireStoreStaff(id){const e=storeStaff.find(x=>x.id===id);if(!e||workshop.storeStaff.includes(id)||!workshop.storeUpgrades.includes('expansion'))return;if(state.balance<e.price)return toast('Nincs elég kredited ehhez a munkatárshoz.');state.balance-=e.price;workshop.storeStaff.push(id);addHistory(`Üzleti munkatárs: ${e.name}`,-e.price);save();saveWorkshop();toast(`${e.name} csatlakozott az üzlethez.`)}
function storeTick(){if(!workshop.storeOwned)return;const now=Date.now();if(!workshop.storeNextPayAt){workshop.storeNextPayAt=now+STORE_CYCLE*1000;localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop));return}if(now<workshop.storeNextPayAt)return;const income=storeCycleIncome();state.balance+=income;workshop.storePending+=income;workshop.storeNextPayAt=now+STORE_CYCLE*1000;if(!workshop.lastStoreHistory||now-workshop.lastStoreHistory>=180000){addHistory('Összesített üzletbevétel',workshop.storePending);workshop.storePending=0;workshop.lastStoreHistory=now}save();saveWorkshop();toast(`Üzleti bevétel: +${fmt(income)} CR`)}
const wheelRewards=[
 {label:'2 000 kredit',weight:20,run:()=>{state.balance+=2000;addHistory('Tech kerék jutalom',2000)}},
 {label:'Használt alkatrész',weight:17,run:()=>giveRandomPart('used')},
 {label:'+30 XP',weight:15,run:()=>{state.xp+=30;updateLevel()}},
 {label:'Normál alkatrész',weight:14,run:()=>giveRandomPart('normal')},
 {label:'Most nincs jutalom',weight:5,run:()=>{}},
 {label:'5 000 kredit',weight:10,run:()=>{state.balance+=5000;addHistory('Tech kerék jutalom',5000)}},
 {label:'Hibás eszköz',weight:8,run:giveBrokenDevice},
 {label:'+60 XP',weight:5,run:()=>{state.xp+=60;updateLevel()}},
 {label:'Prémium alkatrész',weight:4,run:()=>giveRandomPart('premium')},
 {label:'Javított telefon',weight:2,run:()=>workshop.finished.push({type:'phonefix',quality:'used',source:'self',investment:0,completed:Date.now()})}
];
function giveRandomPart(q){const advanced=['consolePower','consoleFan','hdmi','vrDisplay','motion','lens','wheelMotor','pedal','usb'],pool=workshopParts.filter(p=>state.level>=10||!advanced.includes(p.id)),part=pool[Math.floor(Math.random()*pool.length)];ensurePart(part.id)[q]++}
function giveBrokenDevice(){const pool=blueprints.filter(b=>!b.printer&&blueprintAccess(b)),b=pool[Math.floor(Math.random()*pool.length)]||blueprints[0];workshop.projects.push({uid:workshop.nextId++,type:b.id,diagnosed:false,quality:'normal',source:'self',investment:0})}
function weightedRewardIndex(){let roll=Math.random()*wheelRewards.reduce((a,r)=>a+r.weight,0);const index=wheelRewards.findIndex(r=>(roll-=r.weight)<=0);return index<0?0:index}
function updateWheel(){const button=document.querySelector('#spinWheel'),label=document.querySelector('#wheelCooldown');if(!button||wheelBusy)return;const left=Math.max(0,workshop.wheelReadyAt-Date.now());button.disabled=left>0;if(left>0){const total=Math.ceil(left/1000),m=String(Math.floor(total/60)).padStart(2,'0'),s=String(total%60).padStart(2,'0');label.textContent=`Következő pörgetés: ${m}:${s}`}else label.textContent='Pörgetésre kész'}
function spinWheel(){if(wheelBusy||Date.now()<workshop.wheelReadyAt)return;wheelBusy=true;const wheel=document.querySelector('#prizeWheel'),button=document.querySelector('#spinWheel'),index=weightedRewardIndex(),result=wheelRewards[index],sector=360/wheelRewards.length,jitter=(Math.random()-.5)*(sector*.45),landing=(360-(index*sector+sector/2)+jitter+360)%360,turn=1440+landing;button.disabled=true;document.querySelector('#wheelResult').textContent='A kerék forog…';wheel.classList.remove('spinning');wheel.style.transform='rotate(0deg)';wheel.style.setProperty('--wheel-turn',`${turn}deg`);void wheel.offsetWidth;wheel.classList.add('spinning');setTimeout(()=>{result.run();workshop.wheelReadyAt=Date.now()+600000;workshop.wheelSpins++;wheelBusy=false;save();saveWorkshop();document.querySelector('#wheelResult').textContent=`Jutalmad: ${result.label}`;toast(`Tech kerék: ${result.label}`)},4200)}
document.addEventListener('click',e=>{if(e.target.closest('[data-view="workshop"]'))renderWorkshop();if(e.target.closest('[data-view="team"]'))renderEmployees();if(e.target.closest('[data-view="store"]'))renderStore();const salvage=e.target.closest('.salvage-buy');if(salvage)buySalvage(salvage.dataset.blueprint);const part=e.target.closest('.quality-buy');if(part)buyPart(part.dataset.part,part.dataset.quality);const quality=e.target.closest('.quality-select');if(quality)setProjectQuality(quality.dataset.project,quality.dataset.projectQuality);const diagnose=e.target.closest('.diagnose');if(diagnose)startDiagnostic(diagnose.dataset.project);const assemble=e.target.closest('.assemble');if(assemble)startAssembly(assemble.dataset.project);const piece=e.target.closest('.assembly-part');if(piece)chooseAssembly(piece.dataset.assemblyPart);const node=e.target.closest('.circuit-node');if(node)circuitClick(node);const print=e.target.closest('.start-print');if(print)startPrint(print.dataset.print);if(e.target.closest('.buy-printer'))buyPrinter();const list=e.target.closest('.list-market');if(list)listOnMarket(Number(list.dataset.finished));const deliver=e.target.closest('.deliver-order');if(deliver)deliverOrder(Number(deliver.dataset.finished));if(e.target.closest('.accept-offer'))acceptOffer();if(e.target.closest('.decline-offer'))declineOffer();const hire=e.target.closest('.hire-employee');if(hire)hireEmployee(hire.dataset.employee);if(e.target.closest('.buy-store'))buyStore();const upgrade=e.target.closest('.buy-store-upgrade');if(upgrade)buyStoreUpgrade(upgrade.dataset.upgrade);const storeHire=e.target.closest('.hire-store-staff');if(storeHire)hireStoreStaff(storeHire.dataset.storeStaff)});
document.addEventListener('click',e=>{if(e.target.closest('.hire-repair-employee'))hireRepairEmployee();if(e.target.closest('.start-repair-employee'))startRepairEmployee();if(e.target.closest('.start-employee-assembly'))startEmployeeAssembly();const bid=e.target.closest('.accept-bid');if(bid)acceptMarketBid(bid.dataset.listing)});
function commerceTick(){if(!workshop.activeOrder){const now=Date.now();if(workshop.customerOffer&&now>=workshop.offerExpiresAt){workshop.customerOffer=null;generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop))}else if(!workshop.customerOffer&&now>=workshop.offerExpiresAt){generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop))}}settleMarket();employeeTick();storeTick();renderCustomerMarket();renderEmployees();renderStore();updateWheel()}
document.querySelector('#typingInput').addEventListener('input',typingInput);document.querySelector('#closeGame').onclick=closeGame;document.querySelector('#gameModal').addEventListener('click',e=>{if(e.target.id==='gameModal')closeGame()});document.querySelector('#spinWheel').addEventListener('click',spinWheel);document.querySelector('#resetButton').addEventListener('click',()=>{setTimeout(()=>{if(state.balance===150000&&state.level===1&&state.history.length===0){workshop={...emptyWorkshop,parts:{},projects:[],finished:[],marketListings:[],employees:[],employeeTimers:{},storeUpgrades:[],storeStaff:[],nextId:1};saveWorkshop()}},0)});if(!workshop.activeOrder&&!workshop.customerOffer&&Date.now()>=workshop.offerExpiresAt)generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop));setInterval(commerceTick,1000);updateWheel();renderWorkshop();renderEmployees();renderStore();
